/* Service worker. Generated by tools/build.mjs: the cache name and the shell list below are
 * stamped with the build id, so a new build is a new cache and the old one is deleted on
 * activate. There is no version constant to remember to bump, because a constant someone has
 * to remember is a constant that eventually goes stale.
 */
const CACHE = "pay-8a7da444621c";
const SHELL = [
  "./",
  "./app.css?v=8a7da444621c",
  "./app.js?v=8a7da444621c",
  "./qr-art.js?v=8a7da444621c",
  "./qrcode.js?v=8a7da444621c",
  "./data.js?v=8a7da444621c"
];

self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys()
      .then((ks) => Promise.all(ks.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

/* Only ever cache a response that is ours, complete and not the result of a redirect. An
 * unguarded put is how a service worker ends up serving a sign-in page, an error page or a
 * captive-portal page as the app, permanently and invisibly, because the poisoned entry only
 * surfaces once the network is gone. */
function cacheable(r) {
  return r && r.status === 200 && r.type === "basic" && !r.redirected;
}

self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET") return;

  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // Navigations go to the network first so a deploy lands on the next open. Everything else
  // is stamped with the build id in its query string, so a cache hit is by definition the
  // right version and a new build simply misses.
  if (req.mode === "navigate") {
    e.respondWith(
      fetch(req)
        .then((r) => {
          if (cacheable(r)) {
            const copy = r.clone();
            caches.open(CACHE).then((c) => c.put(req, copy)).catch(() => {});
          }
          return r;
        })
        .catch(() => caches.match(req).then((r) => r || caches.match(SHELL[0])))
    );
    return;
  }

  e.respondWith(
    caches.match(req).then((hit) => {
      if (hit) return hit;
      return fetch(req).then((r) => {
        if (cacheable(r)) {
          const copy = r.clone();
          caches.open(CACHE).then((c) => c.put(req, copy)).catch(() => {});
        }
        return r;
      });
    })
  );
});
